package com.restaurant.management.controller;
import com.restaurant.management.dto.*; import com.restaurant.management.enums.ResultatActivite; import com.restaurant.management.service.*; import jakarta.validation.constraints.*; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.validation.annotation.Validated; import org.springframework.web.bind.annotation.*; import java.time.LocalDate;
@Validated @RestController @RequestMapping("/api/tableau-de-bord")
public class TableauBordController {
 private final TableauBordService dashboard; private final ConsultationJournalService journal; public TableauBordController(TableauBordService d,ConsultationJournalService j){dashboard=d;journal=j;}
 @GetMapping("/operations") public TableauBordOperationsResponse operations(@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate debut,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate fin){return dashboard.operations(debut,fin);}
 @GetMapping("/finances") public TableauBordFinancierResponse finances(@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate debut,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate fin){return dashboard.finances(debut,fin);}
 @GetMapping("/journal") public PageResponse<JournalActiviteResponse> journal(@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate debut,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate fin,@RequestParam(required=false) @Size(max=100) String action,@RequestParam(required=false) @Size(max=100) String typeRessource,@RequestParam(required=false) ResultatActivite resultat,@RequestParam(required=false) @Positive Long utilisateurId,@RequestParam(defaultValue="0") @Min(0) int page,@RequestParam(defaultValue="20") @Min(1) @Max(100) int taille,@RequestParam(defaultValue="creeLe") String tri,@RequestParam(defaultValue="desc") String direction){return journal.rechercher(debut,fin,action,typeRessource,resultat,utilisateurId,page,taille,tri,direction);}
 @GetMapping("/journal/utilisateurs") public java.util.List<UtilisateurJournalResponse> utilisateursJournal(){return journal.listerUtilisateurs();}
}
